+// Filters that introduce new colors must not have their result clamped to the
+// palette of an indexed (paletted) PNG source.
+// See issue 12543.
+func TestFilterPalettedPNGIssue12543(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ['page','rss','section','sitemap','taxonomy','term']
+-- assets/bg.png --
+sourcefilename: ../testdata/gohugoio8.png
+-- assets/fg.png --
+sourcefilename: ../testdata/gohugoio24.png
+-- layouts/home.html --
+{{ $bg := resources.Get "bg.png" }}
+{{ $fg := (resources.Get "fg.png").Resize "100x" }}
+{{ $textOpts := dict "color" "#ff0060" "size" 40 "x" 10 "y" 10 }}
+{{ with $bg | resources.Copy "images/bg.png" }}{{ .Publish }}{{ end }}
+{{ with $fg | resources.Copy "images/fg.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Filter (images.Overlay $fg 20 30) | resources.Copy "images/overlay.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Filter (images.Text "Hugo Rocks!" $textOpts) | resources.Copy "images/text.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Filter images.Grayscale | resources.Copy "images/grayscale.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Resize "200x" | resources.Copy "images/resize.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Filter (images.Process "resize 200x") | resources.Copy "images/process.png" }}{{ .Publish }}{{ end }}
+`
+
+	b := hugolib.Test(t, files)
+
+	decode := func(name string) image.Image {
+		t.Helper()
+		img, err := png.Decode(strings.NewReader(b.FileContent("public/images/" + name)))
+		b.Assert(err, qt.IsNil, qt.Commentf(name))
+		return img
+	}
+
+	toNRGBA := func(c color.Color) color.NRGBA {
+		return color.NRGBAModel.Convert(c).(color.NRGBA)
+	}
+
+	bg := decode("bg.png")
+	_, bgIsPaletted := bg.(*image.Paletted)
+	b.Assert(bgIsPaletted, qt.IsTrue)
+
+	// Overlay: every fully opaque pixel of the overlay must be reproduced exactly.
+	fg := decode("fg.png")
+	overlay := decode("overlay.png")
+	_, isPaletted := overlay.(*image.Paletted)
+	b.Assert(isPaletted, qt.IsFalse)
+	var opaque, mismatches int
+	fgb := fg.Bounds()
+	for y := fgb.Min.Y; y < fgb.Max.Y; y++ {
+		for x := fgb.Min.X; x < fgb.Max.X; x++ {
+			fc := toNRGBA(fg.At(x, y))
+			if fc.A != 0xff {
+				continue
+			}
+			opaque++
+			if toNRGBA(overlay.At(x-fgb.Min.X+20, y-fgb.Min.Y+30)) != fc {
+				mismatches++
+			}
+		}
+	}
+	b.Assert(opaque > 0, qt.IsTrue)
+	b.Assert(mismatches, qt.Equals, 0)
+
+	// Text: the exact text color must be present in the result.
+	text := decode("text.png")
+	_, isPaletted = text.(*image.Paletted)
+	b.Assert(isPaletted, qt.IsFalse)
+	want := color.NRGBA{R: 0xff, G: 0x00, B: 0x60, A: 0xff}
+	var found bool
+	tb := text.Bounds()
+	for y := tb.Min.Y; y < tb.Max.Y && !found; y++ {
+		for x := tb.Min.X; x < tb.Max.X; x++ {
+			if toNRGBA(text.At(x, y)) == want {
+				found = true
+				break
+			}
+		}
+	}
+	b.Assert(found, qt.IsTrue)
+
+	// Color adjustments: a grayscale result must only contain gray pixels.
+	gray := decode("grayscale.png")
+	gb := gray.Bounds()
+	var nonGray int
+	for y := gb.Min.Y; y < gb.Max.Y; y++ {
+		for x := gb.Min.X; x < gb.Max.X; x++ {
+			c := toNRGBA(gray.At(x, y))
+			if c.A != 0 && (c.R != c.G || c.G != c.B) {
+				nonGray++
+			}
+		}
+	}
+	b.Assert(nonGray, qt.Equals, 0)
+
+	// Resizing does not introduce new colors, so the source palette is kept.
+	for _, name := range []string{"resize.png", "process.png"} {
+		img := decode(name)
+		p, ok := img.(*image.Paletted)
+		b.Assert(ok, qt.IsTrue, qt.Commentf(name))
+		b.Assert(p.Bounds().Dx(), qt.Equals, 200, qt.Commentf(name))
+	}
+}
