+	imported := hmaps.NewCache[string, resource.Resource]()
+
+	opts.ImportOnResolveFunc = func(imp string, args api.OnResolveArgs) string {
+		if r, found := imported.Get(imp); found {
+			dm.AddIdentity(identity.FirstIdentity(r))
+			return imp
+		}
+
+		switch {
+		case args.Kind == api.ResolveEntryPoint:
+		case args.Importer == stdinImporter:
+		case args.Namespace == NsHugoImport, args.Namespace == NsHugoImportResolveFunc:
+		default:
+			// E.g. an import from node_modules.
+			return ""
+		}
+
+		resolved := ResolveResource(imp, importContext)
+		if resolved == nil {
+			return ""
+		}
+		dm.AddIdentity(identity.FirstIdentity(resolved))
+		resolvePath := PrefixHugoVirtual + resources.InternalResourceTargetPath(resolved)
+		imported.Set(resolvePath, resolved)
+		return resolvePath
+	}
+
+	opts.ImportOnLoadFunc = func(args api.OnLoadArgs) (string, error) {
+		r, found := imported.Get(args.Path)
+		if !found {
+			return "", nil
+		}
+		content, err := resources.InternalResourceSourceContent(ctx, r)
+		if err != nil {
+			return "", fmt.Errorf("failed to read import %q: %w", resources.InternalResourceSourcePathBestEffort(r), err)
+		}
+		return content, nil
+	}
+
+	opts.ErrorMessageResolveFunc = func(msg api.Message) *ErrorMessageResolved {
+		loc := msg.Location
+		if loc == nil {
+			return nil
+		}
+		r, found := imported.Get(strings.TrimPrefix(loc.File, NsHugoImportResolveFunc+":"))
+		if !found {
+			return nil
+		}
+		var contentr hugio.ReadSeekCloser
+		if cp, ok := r.(hugio.ReadSeekCloserProvider); ok {
+			contentr, _ = cp.ReadSeekCloser()
+		}
+		return &ErrorMessageResolved{
+			Content: contentr,
+			Path:    resources.InternalResourceSourcePathBestEffort(r),
+			Message: msg.Text,
+		}
+	}
+
+	opts.ResolveSourceMapSource = func(s string) string {
+		if r, found := imported.Get(s); found {
+			if ss := resources.InternalResourceSourcePath(r); ss != "" {
+				return ss
+			}
+			return PrefixHugoMemory + s
+		}
+		return ""
+	}
+}
