+// ImportContext is a set of resources used to resolve imports
+// (e.g. CSS @import, JS import, Sass @use) in resource transformations
+// such as css.Build, js.Build, js.Batch and css.Sass.
+type ImportContext struct {
+	// Getter resolves imports by name.
+	Getter resource.ResourceGetter
+
+	// key identifies this import context, used in cache keys.
+	key string
+}
+
+// Key returns a key identifying this import context.
+func (ic *ImportContext) Key() string {
+	return ic.key
+}
+
+// NewImportContext creates a new ImportContext from v,
+// which can be a Resource, Resources, a ResourceGetter (e.g. the result of Resources.Mount),
+// something that provides Resources (e.g. a Page) or a slice of any of these.
+func NewImportContext(v any) (*ImportContext, error) {
+	if v == nil {
+		return nil, errors.New("importContext must be set")
+	}
+	getter := resource.NewCachedResourceGetter(v)
+	if !getter.HasDelegates() {
+		return nil, fmt.Errorf("importContext: %T is not a valid import context; expected a Resource, Resources, a Page or a slice of these", v)
+	}
+
+	return &ImportContext{
+		Getter: getter,
+		key:    hashing.HashString(importContextKeyParts(v)),
+	}, nil
+}
+
+// importContextKeyParts returns a hashable representation of v that
+// identifies the resources in it.
+func importContextKeyParts(v any) any {
+	switch vv := v.(type) {
+	case nil:
+		return nil
+	case resource.Resources:
+		parts := make([]any, len(vv))
+		for i, r := range vv {
+			parts[i] = importContextKeyParts(r)
+		}
+		return parts
+	case resource.ResourcesProvider:
+		var self any
+		if id, ok := v.(resource.Identifier); ok {
+			self = id.Key()
+		}
+		return []any{self, importContextKeyParts(vv.Resources())}
+	case resource.Identifier:
+		// The key is not unique for resources with the same name but different content,
+		// e.g. two resources.FromString "foo.css" with different content.
+		if h, ok := importContextContentHash(v); ok {
+			return []any{vv.Key(), h}
+		}
+		return vv.Key()
+	case string:
+		return vv
+	}
+
+	if items, ok := hreflect.ToSliceAny(v); ok {
+		parts := make([]any, len(items))
+		for i, item := range items {
+			parts[i] = importContextKeyParts(item)
+		}
+		return parts
+	}
+
+	// Fall back to the identity of the value, e.g. a func.
+	rv := reflect.ValueOf(v)
+	switch rv.Kind() {
+	case reflect.Func, reflect.Pointer, reflect.Map, reflect.Chan, reflect.UnsafePointer:
+		return fmt.Sprintf("%T:%d", v, rv.Pointer())
+	}
+	return fmt.Sprintf("%T:%v", v, v)
+}
+
+// importContextContentHash returns the content hash of v if v is a resource.
+func importContextContentHash(v any) (uint64, bool) {
+	switch vv := v.(type) {
+	case *resourceAdapter:
+		vv.init(false, false)
+		return vv.target.hash(), true
+	case hashProvider:
+		return vv.hash(), true
+	}
+	return 0, false
+}
+
+// importContextProvider is implemented by resources that may carry an ImportContext.
+type importContextProvider interface {
+	getImportContext() *ImportContext
+}
+
+// importContextSetter is implemented by resources that may carry an ImportContext.
+type importContextSetter interface {
+	setImportContext(*ImportContext)
+}
+
+// InternalResourceImportContext is used internally to get the import context set
+// on a Resource (e.g. via resources.Copy), nil if not set.
+func InternalResourceImportContext(r resource.Resource) *ImportContext {
+	if p, ok := r.(importContextProvider); ok {
+		return p.getImportContext()
+	}
+	return nil
+}
