+// limitations under the License.
+
+package sass
+
+import (
+	"fmt"
+	"path"
+	"strings"
+
+	"github.com/gohugoio/hugo/resources/resource"
+)
+
+// ImportContextURLPrefix is the URL prefix used for imports resolved from an import context
+// (e.g. set via resources.Copy).
+const ImportContextURLPrefix = "hugo-importcontext:"
+
+// ImportContextURL returns the URL for the given import context path.
+func ImportContextURL(p string) string {
+	return ImportContextURLPrefix + "/" + strings.TrimPrefix(p, "/")
+}
+
+// ImportContextPath returns the path for an URL created with ImportContextURL.
+// The second return value is false if url is not an import context URL.
+func ImportContextPath(url string) (string, bool) {
+	p, ok := strings.CutPrefix(url, ImportContextURLPrefix)
+	if !ok {
+		return "", false
+	}
+	// Dart Sass may have resolved a relative import against the
+	// importer's URL, which may add a "//" authority prefix.
+	p = "/" + strings.TrimLeft(p, "/")
+	return path.Clean(p), true
+}
+
+// ResolveImportContext resolves the Sass import url in the given import context.
+// If importerDir is not empty, the url is first resolved relative to that directory.
+// It returns the path of the resolved resource (to be used with ImportContextURL)
+// and the resource, or nil if not found.
+func ResolveImportContext(importContext resource.ResourceGetter, importerDir, url string) (string, resource.Resource) {
+	if importContext == nil {
+		return "", nil
+	}
+
+	url = strings.TrimPrefix(url, "./")
+	if url == "" || strings.Contains(url, ":") {
+		// E.g. hugo:vars, sass:math or an absolute URL.
+		return "", nil
+	}
+
+	var dirs []string
+	if importerDir != "" && importerDir != "." && importerDir != "/" && !strings.HasPrefix(url, "/") {
+		dirs = append(dirs, importerDir)
+	}
+	dirs = append(dirs, "")
+
+	name := path.Base(url)
+	urlDir := path.Dir(url)
+
+	var namePatterns []string
+	if strings.Contains(name, ".") {
+		namePatterns = []string{"_%s", "%s"}
+	} else if strings.HasPrefix(name, "_") {
+		namePatterns = []string{"_%s.scss", "_%s.sass", "_%s.css"}
+	} else {
+		namePatterns = []string{
+			"_%s.scss", "%s.scss",
+			"_%s.sass", "%s.sass",
+			"_%s.css", "%s.css",
+			"%s/_index.scss", "%s/_index.sass",
+			"%s/index.scss", "%s/index.sass",
+		}
+	}
+	name = strings.TrimPrefix(name, "_")
+
+	for _, dir := range dirs {
+		for _, namePattern := range namePatterns {
+			p := path.Join("/", dir, urlDir, fmt.Sprintf(namePattern, name))
+			if r := importContext.Get(p); r != nil {
+				return p, r
+			}
+		}
+	}
+
+	return "", nil
+}
