+func TestContentNodeShifterDeleteMultipleDimensions(t *testing.T) {
+	c := qt.New(t)
+
+	const key = "/blog/a-rather-long-slug"
+	v0 := sitesmatrix.Vector{0, 0, 0}
+	v1 := sitesmatrix.Vector{1, 0, 0}
+	v2 := sitesmatrix.Vector{2, 0, 0}
+
+	tree := newTestContentNodeShifterTree()
+	tree.InsertRaw(key, contentNodes{
+		newTestContentNodeForSite(v0),
+		newTestContentNodeForSite(v1),
+		newTestContentNodeForSite(v2),
+	})
+
+	_, ok := tree.Shape(v1).Delete(key)
+	c.Assert(ok, qt.IsTrue)
+	n, found := tree.GetRaw(key)
+	c.Assert(found, qt.IsTrue)
+	c.Assert(contentNodeSiteVectors(n), qt.DeepEquals, []sitesmatrix.Vector{v0, v2})
+
+	// This used to panic.
+	_, ok = tree.Shape(v2).Delete(key)
+	c.Assert(ok, qt.IsTrue)
+	n, found = tree.GetRaw(key)
+	c.Assert(found, qt.IsTrue)
+	c.Assert(contentNodeSiteVectors(n), qt.DeepEquals, []sitesmatrix.Vector{v0})
+
+	// Deleting again in an already deleted dimension is a no-op.
+	_, ok = tree.Shape(v2).Delete(key)
+	c.Assert(ok, qt.IsFalse)
+
+	_, ok = tree.Shape(v0).Delete(key)
+	c.Assert(ok, qt.IsTrue)
+	_, found = tree.GetRaw(key)
+	c.Assert(found, qt.IsFalse)
+}
+
+func TestContentNodeShifterDeleteFuncRawMultiple(t *testing.T) {
+	c := qt.New(t)
+
+	const key = "/blog/p1"
+	v0 := sitesmatrix.Vector{0, 0, 0}
+	v1 := sitesmatrix.Vector{1, 0, 0}
+	v2 := sitesmatrix.Vector{2, 0, 0}
+	v3 := sitesmatrix.Vector{3, 0, 0}
+
+	tree := newTestContentNodeShifterTree()
+	tree.InsertRaw(key, contentNodes{
+		newTestContentNodeForSite(v0),
+		newTestContentNodeForSite(v1),
+		newTestContentNodeForSite(v2),
+		newTestContentNodeForSite(v3),
+	})
+
+	// Delete two adjacent nodes.
+	_, count := tree.DeleteFuncRaw(key, func(n contentNode) bool {
+		vec := n.(contentNodeForSite).siteVector()
+		return vec == v1 || vec == v2
+	})
+	c.Assert(count, qt.Equals, 2)
+	n, found := tree.GetRaw(key)
+	c.Assert(found, qt.IsTrue)
+	c.Assert(contentNodeSiteVectors(n), qt.DeepEquals, []sitesmatrix.Vector{v0, v3})
+
+	_, count = tree.DeleteFuncRaw(key, func(n contentNode) bool {
+		return true
+	})
+	c.Assert(count, qt.Equals, 2)
+	_, found = tree.GetRaw(key)
+	c.Assert(found, qt.IsFalse)
+}
