+	case hreflect.IsNumber(typ.Kind()):
+		return convertNumber(v, typ)
+	case v.Type().AssignableTo(typ):
+		return v, nil
+	case typ == reflect.TypeFor[string]() && v.Kind() == reflect.String:
+		// Only convert to a plain string; converting to a named string type
+		// (e.g. template.HTML) would mark untrusted content as safe.
+		return v.Convert(typ), nil
+	}
+	return reflect.Value{}, fmt.Errorf("unable to convert value of type %q to %q", v.Type().String(), typ.String())
 }

